// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address newOwner) public {
        // The test contract is the deployer, hence the current owner of c.
        // Any address is admissible for newOwner; no narrow assumptions.
        vm.prank(address(this));
        try c.setOwner(newOwner) {
            // General rule: after the owner calls setOwner(x), the owner IS x.
            assertTrue(c.owner() == newOwner);
        } catch {
            // Must never revert when called by the owner.
            assertTrue(false);
        }
    }
}
